@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.getElementById('order-lines'),add=document.getElementById('add-order-line');let index=1;add?.addEventListener('click',()=>{const row=box.firstElementChild.cloneNode(true);row.querySelectorAll('select,input').forEach(el=>{el.name=el.name.replace(/lines\[\d+\]/,`lines[${index}]`);el.value=''});box.appendChild(row);index++});box?.addEventListener('click',e=>{if(e.target.matches('[data-remove-line]')&&box.children.length>1)e.target.closest('.line-builder').remove()})});</script>@endpush
